import { z } from "zod";
import {
  AuthorIdSchema,
  FaceTagIdSchema,
  MediaIdSchema,
  PersonIdSchema,
} from "./ids.js";
import { BoundingBoxSchema } from "./media.js";

/**
 * Two ways a FaceTag can be created:
 *
 *   auto   — Rekognition `SearchFacesByImage` matched a face above
 *            our confidence threshold against the indexed collection.
 *            `confidence` carries the match score (0–1).
 *
 *   manual — An admin clicked the face in the cms tagger and picked a
 *            person. `confidence` is undefined for manual tags.
 *            `createdById` records who tagged it.
 */
export const FaceTagSourceSchema = z.enum(["auto", "manual"]);

/** Exhaustiveness helper. */
export function assertNeverFaceTagSource(s: never): never {
  throw new Error(`Unhandled face-tag source: ${String(s)}`);
}

/**
 * A single face → person link on a piece of media.
 *
 * Time fields (`startTimeSeconds` / `endTimeSeconds`) are video-only.
 * For images, both are undefined. For Phase B video face tracking, an
 * appearance gets one FaceTag row per contiguous interval the face is
 * on screen — short enough that a hover-tooltip frame can lock to it.
 */
export const FaceTagSchema = z
  .object({
    id: FaceTagIdSchema,
    mediaId: MediaIdSchema,
    personId: PersonIdSchema,
    source: FaceTagSourceSchema,
    /** 0–1 match score from Rekognition. Undefined for manual tags. */
    confidence: z.number().min(0).max(1).optional(),
    boundingBox: BoundingBoxSchema,
    /** Video tag interval start, seconds. Undefined for images. */
    startTimeSeconds: z.number().nonnegative().optional(),
    /** Video tag interval end, seconds. Undefined for images. */
    endTimeSeconds: z.number().nonnegative().optional(),
    /**
     * Author who created the tag. Required for `source: "manual"`,
     * undefined for `source: "auto"` (no human in the loop).
     */
    createdById: AuthorIdSchema.optional(),
    createdAt: z.string().datetime(),
  })
  // If the tag is video-coded, end must be > start.
  .refine(
    (t) =>
      t.startTimeSeconds === undefined ||
      t.endTimeSeconds === undefined ||
      t.endTimeSeconds > t.startTimeSeconds,
    { message: "endTimeSeconds must be greater than startTimeSeconds", path: ["endTimeSeconds"] },
  )
  // Manual tags must record the human; auto tags must not.
  .refine(
    (t) => (t.source === "manual" ? t.createdById !== undefined : t.createdById === undefined),
    {
      message:
        "manual tags require createdById; auto tags must omit it",
      path: ["createdById"],
    },
  )
  // Auto tags must carry a confidence score; manual tags must not.
  .refine(
    (t) => (t.source === "auto" ? t.confidence !== undefined : t.confidence === undefined),
    {
      message:
        "auto tags require confidence; manual tags must omit it",
      path: ["confidence"],
    },
  );
