import { z } from "zod";
import { PersonIdSchema } from "./ids.js";
import { SocialSchema } from "./member.js";
import { AccentSchema, SlugSchema } from "./member.js";
import { CrewRoleSchema } from "./team.js";

/**
 * Three-valued discriminator for {@link PersonSchema}. Each kind carries a
 * different denormalized payload so the renderer can display a Person
 * without a follow-up lookup against `MEMBERS` / `CREW`.
 *
 * Reach for {@link assertNeverPersonKind} when narrowing in a switch.
 */
export const PersonKindSchema = z.enum(["member", "crew", "external"]);

/** Exhaustiveness helper for `switch (kind)` blocks over `PersonKind`. */
export function assertNeverPersonKind(p: never): never {
  throw new Error(`Unhandled person kind: ${String(p)}`);
}

/**
 * Common envelope for every Person variant. Each variant extends this and
 * adds a `kind` literal plus its kind-specific subobject.
 *
 * `consentForFaceIndexing` gates whether this Person's face embeddings get
 * indexed in the Rekognition collection. Defaults false; CORE members /
 * crew flip it true via an explicit admin checkbox during onboarding;
 * external collaborators stay false unless they sign a release. See
 * §"Privacy & consent" in the editorial add-on spec.
 */
const PersonBaseSchema = z.object({
  id: PersonIdSchema,
  consentForFaceIndexing: z.boolean(),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

/**
 * Denormalized member payload carried inside a `kind: "member"` Person.
 * Mirrors the subset of `MemberSchema` the renderer needs, plus the
 * portrait URL (which lives on the DB row, not in the canonical content
 * arrays).
 */
export const MemberPersonDataSchema = z.object({
  slug: SlugSchema,
  name: z.string().min(1),
  realName: z.string().min(1),
  accent: AccentSchema,
  portraitUrl: z.string().url().optional(),
  socials: z.array(SocialSchema).default([]),
});

/** Denormalized crew payload carried inside a `kind: "crew"` Person. */
export const CrewPersonDataSchema = z.object({
  slug: SlugSchema,
  name: z.string().min(1),
  role: CrewRoleSchema,
  avatarUrl: z.string().url().optional(),
  socials: z.array(SocialSchema).default([]),
});

/**
 * Full payload for an external collaborator — someone outside the org's
 * member + crew lists who shows up in an article or gets manually face-
 * tagged on a piece of media.
 */
export const ExternalPersonDataSchema = z.object({
  name: z.string().min(1),
  avatarUrl: z.string().url().optional(),
  bio: z.string().max(500).optional(),
  socials: z.array(SocialSchema).default([]),
});

/** `kind: "member"` variant of {@link PersonSchema}. */
export const MemberPersonSchema = PersonBaseSchema.extend({
  kind: z.literal("member"),
  member: MemberPersonDataSchema,
});

/** `kind: "crew"` variant of {@link PersonSchema}. */
export const CrewPersonSchema = PersonBaseSchema.extend({
  kind: z.literal("crew"),
  crew: CrewPersonDataSchema,
});

/** `kind: "external"` variant of {@link PersonSchema}. */
export const ExternalPersonSchema = PersonBaseSchema.extend({
  kind: z.literal("external"),
  external: ExternalPersonDataSchema,
});

/**
 * The unified tagging entity. Tag this in articles, on media, and against
 * face matches. Discriminated on `kind` — switch with help from
 * {@link assertNeverPersonKind}.
 *
 * Wire shape only: this is what the api hands to consumers, NOT the raw
 * DB row. The api resolves member / crew refs into the embedded data on
 * read.
 */
export const PersonSchema = z.discriminatedUnion("kind", [
  MemberPersonSchema,
  CrewPersonSchema,
  ExternalPersonSchema,
]);
