import { z } from "zod";

/**
 * Tagged-union of every platform we know about, as a Postgres-friendly
 * lowercase string literal. Adding a value here cascades to:
 *
 *   - `coreboys-db` schema (platform enum) — needs a migration.
 *   - `coreboys-api` OpenAPI spec.
 *   - `coreboys-web` `<SocialIcon>` map.
 *
 * Reach for {@link assertNeverPlatform} when narrowing in a switch so the
 * compiler catches a missing branch the moment the union grows.
 */
export const PlatformSchema = z.enum([
  "youtube",
  "tiktok",
  "instagram",
  "twitch",
  "x",
  "snapchat",
  "wikipedia",
]);

/**
 * Per-platform URL host predicates. We deliberately validate the **host**
 * only — paths drift (e.g. YouTube has `/c/`, `/channel/`, `/@handle`,
 * `/user/`), but the host is stable. Returns `true` when the URL belongs
 * to the platform's domain.
 */
const PLATFORM_HOSTS: Record<z.infer<typeof PlatformSchema>, RegExp[]> = {
  youtube: [/(^|\.)youtube\.com$/i, /^youtu\.be$/i],
  tiktok: [/(^|\.)tiktok\.com$/i],
  instagram: [/(^|\.)instagram\.com$/i],
  twitch: [/(^|\.)twitch\.tv$/i],
  // x.com is canonical; twitter.com is the legacy alias we still tolerate.
  x: [/(^|\.)x\.com$/i, /(^|\.)twitter\.com$/i],
  snapchat: [/(^|\.)snapchat\.com$/i],
  wikipedia: [
    /(^|\.)wikipedia\.org$/i,
    /(^|\.)fandom\.com$/i,
    /(^|\.)twitch-streamers\.fandom\.com$/i,
  ],
};

/**
 * @returns true if the URL's host is plausible for the given platform.
 * Used inside `SocialSchema` as a `.refine()`-attached check so a TikTok
 * social pointing at `https://example.com` fails parse.
 */
export function isUrlForPlatform(
  url: string,
  platform: z.infer<typeof PlatformSchema>,
): boolean {
  let host: string;
  try {
    host = new URL(url).host.toLowerCase();
  } catch {
    return false;
  }
  return PLATFORM_HOSTS[platform].some((re) => re.test(host));
}

/**
 * Exhaustiveness helper for `switch (platform)` blocks. Calling this in the
 * `default:` branch turns a missing case into a compile error AND a
 * runtime exception:
 *
 *     switch (platform) {
 *       case "youtube": …; break;
 *       …
 *       default: assertNeverPlatform(platform);
 *     }
 */
export function assertNeverPlatform(p: never): never {
  throw new Error(`Unhandled platform: ${String(p)}`);
}
