import { assertNeverPersonKind } from "../schemas/people.js";
import type { Person } from "../types/people.js";
import type { TalentTag } from "../types/talent-tag.js";

/**
 * Project a {@link Person} into the flat {@link TalentTag} display shape
 * the public-site renderer consumes. Exhaustive over `PersonKind` —
 * adding a new kind to the union turns this into a compile error until
 * the new branch lands.
 *
 * `href` resolution per kind:
 *
 *   - `member`   → `/about/<slug>` (the marketing-site member page)
 *   - `crew`     → `#` (no standalone crew page today; the cms can add
 *                  a `crewSlug → memberSlug` mapping later, at which point
 *                  this resolves to `/about/<memberSlug>`)
 *   - `external` → first social URL, or `#` when the person has no socials
 *
 * `avatarUrl` falls through to the embedded data when present; member
 * variants use `member.portraitUrl`, crew variants use `crew.avatarUrl`,
 * external variants use `external.avatarUrl`.
 */
export function toTalentTag(person: Person): TalentTag {
  switch (person.kind) {
    case "member": {
      const tag: TalentTag = {
        id: person.id,
        kind: "member",
        name: person.member.name,
        href: `/about/${person.member.slug}`,
        socials: person.member.socials,
      };
      if (person.member.portraitUrl !== undefined) {
        tag.avatarUrl = person.member.portraitUrl;
      }
      return tag;
    }

    case "crew": {
      // Crew has no standalone public page today. Returning "#" makes
      // the renderer skip the link affordance — see TalentTagSchema.
      const tag: TalentTag = {
        id: person.id,
        kind: "crew",
        name: person.crew.name,
        href: "#",
        role: person.crew.role,
        socials: person.crew.socials,
      };
      if (person.crew.avatarUrl !== undefined) {
        tag.avatarUrl = person.crew.avatarUrl;
      }
      return tag;
    }

    case "external": {
      const firstSocial = person.external.socials[0]?.url ?? "#";
      const tag: TalentTag = {
        id: person.id,
        kind: "external",
        name: person.external.name,
        href: firstSocial,
        socials: person.external.socials,
      };
      if (person.external.avatarUrl !== undefined) {
        tag.avatarUrl = person.external.avatarUrl;
      }
      return tag;
    }

    default:
      assertNeverPersonKind(person);
  }
}
