import { z } from "zod";
import { PersonIdSchema } from "./ids.js";
import { PersonKindSchema } from "./people.js";
import { CrewRoleSchema } from "./team.js";
import { SocialSchema } from "./member.js";

/**
 * Flat display shape consumed by the public-site renderer. Produced from
 * a `Person` via {@link toTalentTag} so the renderer never branches on
 * `kind` itself — it just renders a name, an avatar, an href, and an
 * optional role + socials.
 *
 * The `href` resolution per kind:
 *   - member   → `/about/<slug>`
 *   - crew     → `#` (today crew has no standalone profile page)
 *   - external → first social URL, or "#" if no socials
 */
export const TalentTagSchema = z.object({
  id: PersonIdSchema,
  kind: PersonKindSchema,
  name: z.string().min(1),
  href: z.string(),
  avatarUrl: z.string().url().optional(),
  role: CrewRoleSchema.optional(),
  socials: z.array(SocialSchema).default([]),
});
